contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry with all logic
    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        // require arrays lengths consistent with how C.transfer uses them: caller expects _tos.length > 0
        require(_tos.length == v.length && _tos.length > 0);

        bool reverted;
        bool ret;
        // call and capture revert vs return using try/catch
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // General property: if the call did not revert then it must have returned true.
        // This asserts that any successful (non-reverting) invocation yields true.
        assert(reverted || ret == true);
    }

    receive() external payable {}
}

